function requireDurableStorage(){if(!s3)throw Object.assign(new Error('Cloudflare R2 storage is not configured. Upload refused.'),{status:503});}
async function putR2(body,key,contentType){requireDurableStorage();await s3.send(new PutObjectCommand({Bucket:R2_BUCKET,Key:key,Body:body,ContentType:contentType||'application/octet-stream'}));return key;}
async function storeVerificationFile(fileOrBuffer,key,contentType){const body=Buffer.isBuffer(fileOrBuffer)?fileOrBuffer:fileOrBuffer?.buffer;if(!body)throw Error('Upload buffer missing');return putR2(body,`verifications/${key}`,contentType);}
async function storeProductFile(fileOrBuffer,key,contentType){const body=Buffer.isBuffer(fileOrBuffer)?fileOrBuffer:fileOrBuffer?.buffer;if(!body)throw Error('Upload buffer missing');return putR2(body,key,contentType);}
async function streamR2(key,res,contentType){requireDurableStorage();try{
  // HTML5 audio/video players use HTTP byte-range requests. R2/S3 supports them,
  // but the app must forward Range and return 206 + Content-Range.
  const range=res.req?.headers?.range;
  const head=await s3.send(new HeadObjectCommand({Bucket:R2_BUCKET,Key:key}));
  const total=Number(head.ContentLength||0);
  const type=contentType||head.ContentType||'application/octet-stream';
  res.set('Content-Type',type);
  res.set('Accept-Ranges','bytes');
  if(range&&total){
    const m=/bytes=(\d*)-(\d*)/.exec(range);
    if(m){
      let start=m[1]?Number(m[1]):0,end=m[2]?Number(m[2]):total-1;
      if(!m[1]&&m[2]){const suffix=Number(m[2]);start=Math.max(0,total-suffix);end=total-1;}
      if(start>=total||start<0||end<start){res.status(416).set('Content-Range',`bytes */${total}`).end();return true;}
      end=Math.min(end,total-1);
      const obj=await s3.send(new GetObjectCommand({Bucket:R2_BUCKET,Key:key,Range:`bytes=${start}-${end}`}));
      res.status(206);res.set('Content-Range',`bytes ${start}-${end}/${total}`);res.set('Content-Length',String(end-start+1));
      const part=obj.Body;res.on('close',()=>{try{part.destroy?.()}catch{}});part.on('error',()=>res.destroy());part.pipe(res);return true;
    }
  }
  const obj=await s3.send(new GetObjectCommand({Bucket:R2_BUCKET,Key:key}));
  if(total)res.set('Content-Length',String(total));const whole=obj.Body;res.on('close',()=>{try{whole.destroy?.()}catch{}});whole.on('error',()=>res.destroy());whole.pipe(res);return true;
}catch(e){if(e?.$metadata?.httpStatusCode===404||e?.name==='NoSuchKey'||e?.name==='NotFound')return false;throw e;}}
async function streamProductFile(key,res,contentType){return streamR2(key,res,contentType);}
