async function applySettlementDecision(dispute, job, decision, actorId){
  await q("UPDATE disputes SET status='DECIDED',decision=$1 WHERE id=$2",[JSON.stringify(decision),dispute.id]);
  const updated=(await q("UPDATE jobs SET status='RESOLVED_RELEASE',payment_status='RELEASE_PENDING',resolution=$1 WHERE id=$2 RETURNING *",[JSON.stringify(decision),job.id])).rows[0];
  if(decision.clientPercent>0){ try{ const p=(await q('SELECT * FROM payments WHERE job_id=$1 ORDER BY created_at DESC LIMIT 1',[job.id])).rows[0]; if(p&&['HELD','RELEASE_PENDING','FROZEN'].includes(p.status)) await refundDisputeShare(updated,p,decision.clientPercent,actorId); }catch(e){ console.error('Settlement refund failed:',e.message); notifyAdmin('Settlement refund failed',`Job ${job.id}: ${e.message}`); } }
  let payoutNote=null;
  if(decision.talentPercent>0){ try{ await releasePayoutForJob(updated.id,actorId); }catch(e){ payoutNote=e.message; } }
  return {job:updated,payoutNote};
}
