async function sendMail(to,subject,text){
  if(RESEND_API_KEY){
    const r=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:`Bearer ${RESEND_API_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({from:RESEND_FROM,to:[to],subject,text})});
    const data=await r.json().catch(()=>({}));
    if(!r.ok)throw Error(data.message||data.error?.message||`Resend send failed (${r.status})`);
    return data;
  }
  if(!smtpMailer)return false;
  return smtpMailer.sendMail({from:process.env.MAIL_FROM||process.env.SMTP_USER,to,subject,text});
}
function sendMailAsync(to,subject,text){if(!emailConfigured)return;sendMail(to,subject,text).catch(e=>console.error('Email send failed:',e.message));}
