// SMS: Robase transactional SMS + OTP integration.
// Configure ROBASE_API_KEY in Render. Robase uses Bearer auth at https://api.robase.dev.
const ROBASE_API_KEY=String(process.env.ROBASE_API_KEY||'').trim();
const ROBASE_BASE_URL=String(process.env.ROBASE_BASE_URL||'https://api.robase.dev').replace(/\/$/,'');
const smsConfigured=Boolean(ROBASE_API_KEY);
function normalizeSmsPhone(phone){const raw=String(phone||'').trim();if(!raw)return '';if(raw.startsWith('+'))return '+'+raw.slice(1).replace(/\D/g,'');const digits=raw.replace(/\D/g,'');if(digits.startsWith('234'))return '+'+digits;if(digits.startsWith('0')&&digits.length===11)return '+234'+digits.slice(1);return digits?('+'+digits):'';}
async function robaseRequest(path,{method='GET',body=null,headers={}}={}){
  if(!smsConfigured)throw Error('Robase SMS is not configured');
  const h={Authorization:`Bearer ${ROBASE_API_KEY}`,'Content-Type':'application/json',...headers};
  const r=await fetch(`${ROBASE_BASE_URL}${path}`,{method,headers:h,body:body==null?undefined:JSON.stringify(body)});
  const text=await r.text(); let data={};
  try{data=text?JSON.parse(text):{}}catch{data={raw:text}}
  if(!r.ok)throw Error(data.message||data.error||`Robase request failed (${r.status}): ${text.slice(0,300)}`);
  return data;
}
async function sendSms(to,body,metadata={}){
  if(!smsConfigured||!to)return false;
  return robaseRequest('/v1/sms/send',{method:'POST',body:{phone_number:normalizeSmsPhone(to),message:String(body).slice(0,1500),metadata}});
}
function sendSmsAsync(to,body,metadata={}){if(!smsConfigured)return;sendSms(to,body,metadata).catch(e=>console.error('Robase SMS send failed:',e.message));}
async function sendOtp(to){
  return robaseRequest('/v1/otp/send',{method:'POST',body:{phone_number:normalizeSmsPhone(to),code_length:6,ttl_seconds:600}});
}
async function verifyOtp(otpId,code){
  return robaseRequest('/v1/otp/verify',{method:'POST',body:{otp_id:String(otpId),code:String(code)}});
}
async function sendUserFundedSms(userId,to,body,kind='notification'){
  if(!smsConfigured||!to)return {sent:false,reason:'sms_not_configured'};
  const price=Math.max(0,Number(await setting('smsUserPriceNgn',10))||10);
  const c=await pool.connect(); let ref=null;
  try{
    await c.query('BEGIN');
    await c.query('SELECT id FROM users WHERE id=$1 FOR UPDATE',[userId]);
    const br=await c.query("SELECT COALESCE(SUM(amount),0) total FROM wallet_ledger WHERE user_id=$1 AND (status='COMPLETED' OR (status='PROCESSING' AND type IN ('WITHDRAWAL','SMS_CHARGE')))",[userId]);
    const balance=Number(br.rows[0].total);
    if(balance<price){await c.query('ROLLBACK');return {sent:false,reason:'insufficient_wallet_balance',price,balance};}
    ref=`SMS_${String(userId).replace(/-/g,'').slice(0,10)}_${Date.now()}_${crypto.randomBytes(3).toString('hex')}`;
    await c.query("INSERT INTO wallet_ledger(user_id,type,amount,reference,status,meta) VALUES($1,'SMS_CHARGE',$2,$3,'PROCESSING',$4)",[userId,-price,ref,JSON.stringify({kind,to:String(to).slice(-6)})]);
    await c.query('COMMIT');
  }catch(e){try{await c.query('ROLLBACK')}catch{} throw e}finally{c.release()}
  try{
    const provider=await sendSms(to,body,{prodilive_user_id:String(userId),kind,reference:ref});
    const providerId=provider?.id||provider?.message_id||null;
    const creditCost=Number(provider?.credit_cost||0)||null;
    await q("UPDATE wallet_ledger SET status='COMPLETED',meta=COALESCE(meta,'{}'::jsonb)||$1::jsonb WHERE reference=$2 AND user_id=$3 AND type='SMS_CHARGE'",[JSON.stringify({provider:'robase',providerId,creditCost,providerStatus:provider?.status||'queued'}),ref,userId]);
    if(price>0)await q("INSERT INTO platform_ledger(type,amount,reference,status,meta) VALUES('SMS_ALERT_CHARGE',$1,$2,'COMPLETED',$3) ON CONFLICT(reference) DO NOTHING",[price,'PLATFORM_'+ref,JSON.stringify({userId,kind,provider:'robase',providerId,creditCost})]);
    return {sent:true,price,reference:ref,providerId,creditCost};
  }catch(e){
    await q("UPDATE wallet_ledger SET status='FAILED',meta=COALESCE(meta,'{}'::jsonb)||$1::jsonb WHERE reference=$2 AND user_id=$3 AND type='SMS_CHARGE'",[JSON.stringify({error:String(e.message||e).slice(0,300)}),ref,userId]).catch(()=>{});
    console.error('Funded SMS send failed:',e.message); return {sent:false,reason:'provider_failed'};
  }
}
function sendUserFundedSmsAsync(userId,to,body,kind){sendUserFundedSms(userId,to,body,kind).catch(e=>console.error('Funded SMS failed:',e.message));}
async function notifyWithPrefs(userId,type,title,body,meta={},smsKind=null){await q('INSERT INTO notifications(user_id,type,title,body,meta) VALUES($1,$2,$3,$4,$5)',[userId,type,title,body,meta]);const r=await q('SELECT email,phone,email_job_alerts,sms_job_alerts,sms_deadline_alerts,sms_transaction_alerts,phone_verified FROM users WHERE id=$1',[userId]);const u=r.rows[0];if(!u)return;if(emailConfigured&&u.email)sendMailAsync(u.email,`PRODILIVE — ${title}`,`${body}\n\nOpen PRODILIVE: ${APP_ORIGIN}`);const smsAllowed=smsKind==='job'?u.sms_job_alerts:smsKind==='deadline'?u.sms_deadline_alerts:smsKind==='transaction'?u.sms_transaction_alerts:false;if(smsAllowed&&u.phone&&u.phone_verified)sendUserFundedSmsAsync(userId,u.phone,`PRODILIVE: ${title}. ${body} ${APP_ORIGIN}`,smsKind);}

