// Audio/video players fire many byte-range requests (every seek, every buffer refill), so protected media
// streams get their own generous bucket instead of eating the 300-per-15-min budget of the normal API.
const MEDIA_ROUTE_RE=/^\/api\/(?:files\/[^/]+\/(?:preview|master)|project-attachments\/[^/]+\/file|products\/[^/]+\/preview)$/;
const isMediaReq=req=>req.method==='GET'&&MEDIA_ROUTE_RE.test(String(req.originalUrl||'').split('?')[0]);
app.use('/api/', rateLimit({windowMs:15*60*1000,max:300,standardHeaders:true,legacyHeaders:false,skip:isMediaReq}));
app.use('/api/', rateLimit({windowMs:15*60*1000,max:3000,standardHeaders:true,legacyHeaders:false,skip:req=>!isMediaReq(req)}));
