function token(req){return (req.headers.authorization||'').replace(/^Bearer\s+/i,'').trim();}
async function auth(req,res,next){try{const t=token(req);if(!t)return res.status(401).json({error:'Authentication required'});const r=await q(`SELECT u.*,s.expires_at FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=$1`,[sha(t)]);const u=r.rows[0];if(!u||new Date(u.expires_at)<=new Date())return res.status(401).json({error:'Invalid or expired session'});if(['SUSPENDED','DELETED'].includes(u.status))return res.status(403).json({error:'Account suspended'});req.user=u;req.tokenHash=sha(t);next()}catch(e){next(e)}}
const roles=(...rs)=>(req,res,next)=>rs.includes(req.user.role)?next():res.status(403).json({error:'Insufficient permissions'});
const requireVerified=(req,res,next)=>(req.user.email_verified||req.user.role==='admin')?next():res.status(403).json({error:'Please verify your email address before doing this. Check your inbox for a verification link.'});

// ---- Signed media URLs ----
// <audio>, <video> and <a> elements cannot send an "Authorization: Bearer" header, so a plain
// <audio src="/api/files/.../preview"> always got a 401 and never played. Protected media routes therefore
// also accept a short-lived token (?mt=) that is bound to ONE path and ONE user and is signed with an HMAC.
// The route's normal permission check still runs for that user, so a token never grants more than the user already has.
const MEDIA_TTL_SEC=Math.min(3600,Math.max(300,Number(process.env.MEDIA_TTL_SEC||900)));
const MEDIA_SECRET=process.env.MEDIA_SIGNING_SECRET||((process.env.DATABASE_URL&&(process.env.R2_SECRET_ACCESS_KEY||process.env.S3_SECRET_ACCESS_KEY))?crypto.createHash('sha256').update('prodilive-media|'+process.env.DATABASE_URL+'|'+(process.env.R2_SECRET_ACCESS_KEY||process.env.S3_SECRET_ACCESS_KEY)).digest('hex'):crypto.randomBytes(32).toString('hex'));
const MEDIA_PATH_RES=[/^\/api\/files\/[0-9a-f-]{36}\/(?:preview|master)$/i,/^\/api\/project-attachments\/[0-9a-f-]{36}\/file$/i];
function signMediaPath(p,userId){const body=Buffer.from(JSON.stringify({p,u:String(userId),e:Math.floor(Date.now()/1000)+MEDIA_TTL_SEC})).toString('base64url');return `${body}.${crypto.createHmac('sha256',MEDIA_SECRET).update(body).digest('base64url')}`}
function verifyMediaToken(t,p){try{const [body,sig]=String(t||'').split('.');if(!body||!sig)return null;const want=Buffer.from(crypto.createHmac('sha256',MEDIA_SECRET).update(body).digest('base64url')),got=Buffer.from(sig);if(got.length!==want.length||!crypto.timingSafeEqual(got,want))return null;const d=JSON.parse(Buffer.from(body,'base64url').toString());if(d.p!==p||!(d.e>Date.now()/1000))return null;return d.u}catch{return null}}
async function mediaAuth(req,res,next){if(token(req))return auth(req,res,next);try{const userId=verifyMediaToken(req.query.mt,req.path);if(!userId)return res.status(401).json({error:'Authentication required'});const u=(await q('SELECT * FROM users WHERE id=$1',[userId])).rows[0];if(!u||['SUSPENDED','DELETED'].includes(u.status))return res.status(403).json({error:'Account suspended'});req.user=u;next()}catch(e){next(e)}}
app.post('/api/media/sign',auth,(req,res)=>{const b=req.body||{},paths=(Array.isArray(b.paths)?b.paths:[b.path]).filter(x=>typeof x==='string').slice(0,100),urls={};for(const p of paths){const clean=p.split('?')[0];if(MEDIA_PATH_RES.some(r=>r.test(clean)))urls[p]=`${clean}?mt=${signMediaPath(clean,req.user.id)}`}res.json({urls})});
