app.get('/api/payout/banks',auth,async(req,res)=>{try{const country=String(req.query.country||'NG').toUpperCase(),m=PAYOUT_MARKETS[country];if(!m)return res.status(400).json({error:'Unsupported payout country'});const banks=await paystack('/bank?currency='+encodeURIComponent(m.currency));res.json({country,currency:m.currency,banks:(banks||[]).filter(b=>b.active!==false).map(b=>({name:b.name,code:String(b.code||b.slug||''),slug:b.slug||null}))})}catch(e){console.error('Bank list failed:',e.message);res.status(400).json({error:e.message||'Could not load banks'})}});
app.get('/api/payout/resolve-account',auth,async(req,res)=>{try{const country=String(req.query.country||'NG').toUpperCase(),m=PAYOUT_MARKETS[country];const bankCode=String(req.query.bankCode||'').trim(),accountNumber=String(req.query.accountNumber||'').trim();if(!m)return res.status(400).json({error:'Unsupported payout country'});if(!bankCode||accountNumber.length<5)return res.status(400).json({error:'Choose a valid bank and enter the account number'});if(!m.autoName)return res.status(400).json({error:`Automatic account-name lookup is not available through Paystack for ${m.name}. This payout method is not enabled yet.`});const d=await paystack('/bank/resolve?account_number='+encodeURIComponent(accountNumber)+'&bank_code='+encodeURIComponent(bankCode));res.json({accountName:d.account_name,accountNumber:d.account_number||accountNumber,bankCode,country,currency:m.currency})}catch(e){console.error('Account resolve failed:',e.message);res.status(400).json({error:e.message||'We could not verify that bank account.'})}});
app.get('/api/wallet/balance',auth,async(req,res,next)=>{try{await reconcilePendingWalletDeposits(req.user.id);const r=await q("SELECT COALESCE(SUM(amount),0) total FROM wallet_ledger WHERE user_id=$1 AND (status='COMPLETED' OR (type='WITHDRAWAL' AND status='PROCESSING'))",[req.user.id]);const byType=await q("SELECT type,COALESCE(SUM(amount),0) total FROM wallet_ledger WHERE user_id=$1 AND status='COMPLETED' GROUP BY type",[req.user.id]);const totals=Object.fromEntries(byType.rows.map(x=>[x.type,Number(x.total)]));let held=0;if(req.user.role==='member'){const h=await q("SELECT COALESCE(SUM(p.amount),0) total FROM payments p JOIN jobs j ON j.id=p.job_id WHERE (j.client_id=$1 OR j.talent_id=$1) AND p.status IN ('HELD','RELEASE_PENDING','FROZEN')",[req.user.id]);held=Number(h.rows[0].total)}else if(req.user.role==='client'){const h=await q("SELECT COALESCE(SUM(p.amount),0) total FROM payments p JOIN jobs j ON j.id=p.job_id WHERE j.client_id=$1 AND p.status IN ('HELD','RELEASE_PENDING','FROZEN')",[req.user.id]);held=Number(h.rows[0].total)}else if(req.user.role==='talent'){const h=await q("SELECT COALESCE(SUM(p.amount),0) total FROM payments p JOIN jobs j ON j.id=p.job_id WHERE j.talent_id=$1 AND p.status IN ('HELD','RELEASE_PENDING','FROZEN')",[req.user.id]);held=Number(h.rows[0].total)}res.json({balance:Number(r.rows[0].total),heldFunds:held,totalDeposits:totals.DEPOSIT||0,totalEarnings:totals.JOB_EARNING||0,totalWithdrawals:Math.abs(totals.WITHDRAWAL||0),totalRefunds:totals.REFUND||0,totalSmsCharges:Math.abs(totals.SMS_CHARGE||0),smsPriceNgn:Number(await setting('smsUserPriceNgn',10))})}catch(e){next(e)}});
