// Delivery files, project attachments and marketplace masters accept any audio or video, images, PDF, Office documents
// and archives. Browsers often report audio as an empty or generic type (.flac, .aif, .m4a on Windows, etc.), so the
// file extension is used as a fallback and the stored type is normalised to one that browsers can play.
const EXT_MIME={mp3:'audio/mpeg',wav:'audio/wav',wave:'audio/wav',bwf:'audio/wav',m4a:'audio/mp4',aac:'audio/aac',flac:'audio/flac',ogg:'audio/ogg',oga:'audio/ogg',opus:'audio/ogg',aif:'audio/aiff',aiff:'audio/aiff',aifc:'audio/aiff',caf:'audio/x-caf',wma:'audio/x-ms-wma',weba:'audio/webm',mid:'audio/midi',midi:'audio/midi',
mp4:'video/mp4',m4v:'video/mp4',mov:'video/quicktime',webm:'video/webm',avi:'video/x-msvideo',mkv:'video/x-matroska',
pdf:'application/pdf',zip:'application/zip',rar:'application/vnd.rar','7z':'application/x-7z-compressed',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',webp:'image/webp',
txt:'text/plain',csv:'text/csv',rtf:'application/rtf',doc:'application/msword',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xls:'application/vnd.ms-excel',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',ppt:'application/vnd.ms-powerpoint',pptx:'application/vnd.openxmlformats-officedocument.presentationml.presentation',
flp:'application/octet-stream',als:'application/octet-stream',rpp:'application/octet-stream',cpr:'application/octet-stream',ptx:'application/octet-stream',sesx:'application/octet-stream',song:'application/octet-stream'};
const EXTRA_UPLOAD_MIMES=new Set(['application/x-zip-compressed','application/x-zip','application/zip','application/pdf','application/rtf','application/msword','application/vnd.ms-excel','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.openxmlformats-officedocument.presentationml.presentation','application/vnd.rar','application/x-rar-compressed','application/x-7z-compressed','text/plain','text/csv','image/png','image/jpeg','image/gif','image/webp']);
const GENERIC_MIMES=new Set(['','application/octet-stream','binary/octet-stream','application/x-unknown','application/unknown']);
function mediaFileFilter(req,file,cb){
  const ext=path.extname(file.originalname||'').slice(1).toLowerCase(),rep=String(file.mimetype||'').toLowerCase().split(';')[0].trim(),extMime=EXT_MIME[ext];
  if(file.fieldname==='cover'){const okCover=['image/jpeg','image/png'].includes(rep)||(GENERIC_MIMES.has(rep)&&['jpg','jpeg','png'].includes(ext));if(!okCover)return cb(Object.assign(new Error('Thumbnail must be a JPG or PNG image'),{code:'LIMIT_UNEXPECTED_FILE'}));file.mimetype=extMime&&GENERIC_MIMES.has(rep)?extMime:rep;return cb(null,true)}
  let mime=rep,ok=false;
  if(extMime&&(GENERIC_MIMES.has(rep)||rep.startsWith('audio/')||rep.startsWith('video/'))){
    // Preserve the browser-reported media family. A .webm voice note is commonly audio/webm;
    // coercing it to video/webm makes some browsers refuse to render it as audio.
    if(rep.startsWith('audio/')&&extMime.startsWith('video/')) mime=rep;
    else if(rep.startsWith('video/')&&extMime.startsWith('audio/')) mime=rep;
    else mime=extMime;
    ok=true
  }
  else if(rep.startsWith('audio/')||rep.startsWith('video/')||EXTRA_UPLOAD_MIMES.has(rep)||ALLOWED_UPLOAD_MIMES.has(rep))ok=true;
  if(!ok)return cb(Object.assign(new Error('Unsupported file type. You can upload audio, video, images, PDF, Office documents and ZIP archives.'),{code:'LIMIT_UNEXPECTED_FILE'}));
  file.mimetype=mime;cb(null,true);
}
