const WATERMARK_CLIP = path.join(ROOT,'assets','prodilive-watermark-natural-male.wav');
// PRODILIVE never synthesizes the commercial watermark with eSpeak/robotic TTS.
// Supply a real, human-recorded male voice saying exactly "Prodilive.com" at this path.
// The same clip is mixed at 0s, 10s, 20s, 30s... into protected delivery/marketplace previews.
function requireNaturalWatermark(){
  if(!fs.existsSync(WATERMARK_CLIP)) throw Object.assign(new Error('Natural PRODILIVE watermark voice is not installed. Add assets/prodilive-watermark-natural-male.wav (male voice saying “Prodilive.com”).'),{status:503});
  return WATERMARK_CLIP;
}
async function makePreview(input,out,mime){
  try{
    const voice=requireNaturalWatermark();
    const probe=await exec('ffprobe',['-v','error','-show_entries','format=duration','-of','default=nw=1:nk=1',input],{timeout:20000});
    const duration=Math.max(1,Math.min(Number(String(probe.stdout||'').trim())||40,Number(process.env.PREVIEW_MAX_SECONDS||180)));
    const times=[]; for(let t=0;t<duration;t+=10) times.push(t);
    // One natural spoken clip, delayed copies every ten seconds. The source remains audible beneath it.
    const inputs=['-i',input]; for(let i=0;i<times.length;i++) inputs.push('-i',voice);
    const parts=[`[0:a]atrim=0:${duration},asetpts=PTS-STARTPTS,volume=0.92[main]`];
    const labels=['[main]'];
    times.forEach((t,i)=>{parts.push(`[${i+1}:a]adelay=${Math.round(t*1000)}|${Math.round(t*1000)},volume=1.0[wm${i}]`);labels.push(`[wm${i}]`)});
    parts.push(`${labels.join('')}amix=inputs=${labels.length}:duration=first:dropout_transition=0[mixed]`);
    await exec('ffmpeg',['-y',...inputs,'-filter_complex',parts.join(';'),'-map','[mixed]','-t',String(duration),'-vn','-c:a','aac','-b:a','160k','-movflags','+faststart','-metadata','comment=PRODILIVE PROTECTED PREVIEW - NOT LICENSED FOR USE',out],{timeout:180000});
    return true;
  }catch(e){console.error('preview',e.message);return false}
}
async function makeVisualPreview(input,out,mime,watermark){
  try{
    const safeText=String(watermark||'PRODILIVE PROTECTED PREVIEW').replace(/[:'\\]/g,' ');
    if(/^image\//.test(mime)){
      await exec('ffmpeg',['-y','-i',input,'-vf',`scale='min(1400,iw)':-2,drawtext=text='${safeText}':x=(w-text_w)/2:y=(h-text_h)/2:fontsize=h/14:fontcolor=white@0.55:box=1:boxcolor=black@0.20:boxborderw=18`,'-frames:v','1','-q:v','5',out],{timeout:120000});
      return 'image/jpeg';
    }
    if(/^video\//.test(mime)){
      await exec('ffmpeg',['-y','-i',input,'-vf',`scale='min(1280,iw)':-2,drawtext=text='${safeText}':x='mod(t*95,w-text_w)':y='h*0.12+mod(t*37,h*0.55)':fontsize=h/18:fontcolor=white@0.62:box=1:boxcolor=black@0.18:boxborderw=12`,'-c:v','libx264','-preset','veryfast','-crf','28','-c:a','aac','-b:a','96k','-movflags','+faststart',out],{timeout:180000});
      return 'video/mp4';
    }
    return null;
  }catch(e){console.error('visual preview',e.message);return null}
}
app.post('/api/jobs/:id/deliver',auth,roles('member','talent','client'),uploadMedia.array('files',25),async(req,res,next)=>{try{const j=(await q('SELECT * FROM jobs WHERE id=$1 AND talent_id=$2',[req.params.id,req.user.id])).rows[0];if(!j)return res.sendStatus(404);if(!['IN_PROGRESS','REVISION_REQUESTED'].includes(j.status))return res.status(400).json({error:'Job is not accepting delivery'});if(!req.files?.length)return res.status(400).json({error:'At least one file is required'});const submission=uid(),items=[];for(const f of req.files){const safe=path.basename(f.originalname).replace(/[^a-zA-Z0-9._-]/g,'_');const base=`${submission}_${uid()}_${safe}`;const masterKey=`jobs/masters/${base}`;const digest=crypto.createHash('sha256').update(f.buffer).digest('hex');const ext=/^image\//.test(f.mimetype)?'.jpg':/^video\//.test(f.mimetype)?'.mp4':'.m4a';const inputTmp=path.join(TMP,`input_${uid()}${path.extname(f.originalname).slice(0,10)}`),previewTmp=path.join(TMP,`preview_${uid()}${ext}`);let previewMade=false,previewMime=null;try{if(/^audio\//.test(f.mimetype)){fs.writeFileSync(inputTmp,f.buffer);previewMade=await makePreview(inputTmp,previewTmp,f.mimetype);if(previewMade)previewMime='audio/mp4'}else if(/^(image|video)\//.test(f.mimetype)){fs.writeFileSync(inputTmp,f.buffer);previewMime=await makeVisualPreview(inputTmp,previewTmp,f.mimetype,`PRODILIVE PREVIEW • PROJECT ${j.id} • CLIENT ${j.client_id}`);previewMade=Boolean(previewMime)}}finally{if(fs.existsSync(inputTmp))fs.unlinkSync(inputTmp)}await storeJobObject(f,masterKey,f.mimetype);const r=await q(`INSERT INTO files(job_id,submission_id,original_name,stored_name,mime,size,sha256) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING *`,[j.id,submission,f.originalname,masterKey,f.mimetype,f.size,digest]);const file=r.rows[0];if(previewMade&&fs.existsSync(previewTmp)){const previewKey=`jobs/previews/${file.id}${ext}`;await storeJobObject(fs.readFileSync(previewTmp),previewKey,previewMime);fs.unlinkSync(previewTmp);await q('UPDATE files SET preview_name=$1 WHERE id=$2',[previewKey,file.id]);file.preview_name=previewKey}items.push(file)}const rw=Number(await setting('reviewWindowHours',48));await q("UPDATE jobs SET submission_id=$1,status='CLIENT_REVIEW',submitted_at=now(),review_deadline=now()+($2::text || ' hours')::interval,qa=$3 WHERE id=$4",[submission,String(rw),JSON.stringify({technical:'NOT_REQUIRED',human:'CLIENT_REVIEW',notes:[]}),j.id]);await audit('DELIVERY_SUBMITTED',req.user.id,{jobId:j.id,submissionId:submission,fileCount:items.length});await notify(j.client_id,'DELIVERY','Delivery submitted',`A protected delivery for “${j.title}” is ready for review. Originals remain locked until completion.`,{jobId:j.id});res.json({jobId:j.id,submissionId:submission,files:items.map(f=>({id:f.id,name:f.original_name,previewUrl:f.preview_name?`/api/files/${f.id}/preview`:null,downloadUrl:`/api/files/${f.id}/master`}))})}catch(e){for(const f of req.files||[])if(f.path&&fs.existsSync(f.path))fs.unlinkSync(f.path);next(e)}});
async function fileFor(fid){return (await q('SELECT f.*,j.client_id,j.talent_id,j.status,j.payment_status FROM files f JOIN jobs j ON j.id=f.job_id WHERE f.id=$1',[fid])).rows[0]}
