app.post('/api/jobs/:id/dispute',auth,async(req,res,next)=>{try{const j=(await q('SELECT * FROM jobs WHERE id=$1',[req.params.id])).rows[0];if(!j||![j.client_id,j.talent_id].includes(req.user.id))return res.sendStatus(404);if(['RELEASED','CANCELLED'].includes(j.status))return res.status(400).json({error:'Job already closed'});if((await q("SELECT 1 FROM disputes WHERE job_id=$1 AND status IN ('OPEN','ASSIGNED')",[j.id])).rowCount)return res.status(409).json({error:'An active dispute already exists'});const code=String(req.body.cancellationCode||'OTHER').slice(0,80);if(!DISPUTE_CODES.has(code))return res.status(400).json({error:'That reason belongs to Cancel project, not Open a dispute'});const detail=String(req.body.reason||'').trim();if(detail.length<10)return res.status(400).json({error:'Please describe what happened in a bit more detail'});const settlementHours=Number(await setting('disputeSettlementHours',24));const reviewerHours=Number(await setting('reviewerResolutionHours',48));const r=await q("INSERT INTO disputes(job_id,opened_by,reason,evidence,settlement_deadline,reviewer_action_deadline,kind,requires_reviewer) VALUES($1,$2,$3,$4,now()+($5::text||' hours')::interval,now()+(($5+$6)::text||' hours')::interval,'DISPUTE',true) RETURNING *",[j.id,req.user.id,detail.slice(0,5000),Array.isArray(req.body.evidence)?req.body.evidence:[],settlementHours,reviewerHours]);await q('UPDATE disputes SET cancellation_code=$1 WHERE id=$2',[code,r.rows[0].id]);r.rows[0].cancellation_code=code;await q("UPDATE jobs SET status='DISPUTED',payment_status='FROZEN' WHERE id=$1",[j.id]);await audit('DISPUTE_OPENED',req.user.id,{jobId:j.id,disputeId:r.rows[0].id});io.to('reviewers').emit('dispute:new',{disputeId:r.rows[0].id,jobTitle:j.title});const otherParty=String(req.user.id)===String(j.client_id)?j.talent_id:j.client_id;io.to('user:'+otherParty).emit('dispute:onyourjob',{jobId:j.id,disputeId:r.rows[0].id});notify(otherParty,'DISPUTE_OPENED','A dispute was opened',`A dispute was opened on "${j.title}". Funds are frozen while a reviewer looks into it — you can add context in the project chat.`,{jobId:j.id});notifyAdmin('New dispute opened',`A dispute was opened on "${j.title}". Online reviewers have been alerted; you can also assign one manually from the admin Disputes tab.`);res.status(201).json(r.rows[0])}catch(e){next(e)}});
app.post('/api/jobs/:id/cancel-request',auth,async(req,res,next)=>{try{const j=(await q('SELECT * FROM jobs WHERE id=$1',[req.params.id])).rows[0];if(!j||![j.client_id,j.talent_id].includes(req.user.id))return res.sendStatus(404);if(['RELEASED','CANCELLED'].includes(j.status))return res.status(400).json({error:'Job already closed'});if((await q("SELECT 1 FROM disputes WHERE job_id=$1 AND status IN ('OPEN','ASSIGNED')",[j.id])).rowCount)return res.status(409).json({error:'An active cancellation or dispute is already open on this project'});const code=String(req.body.cancellationCode||'').slice(0,80);if(!CANCEL_CODES.has(code))return res.status(400).json({error:'That reason belongs to Open a dispute, not Cancel project'});const detail=String(req.body.reason||'').trim();if(detail.length<10)return res.status(400).json({error:'Please briefly explain your reason for cancelling'});const voluntary=Math.max(0,Math.min(100,Number(req.body.clientVoluntaryPercent||0)));const defaultTalentPercent={CHANGE_MIND:20,CREATIVE_DIRECTION:30,NOT_SATISFIED:25,MUTUAL:0}[code]||0;const suggested=Math.max(defaultTalentPercent,voluntary);const priorCancels=await recentSoftCancelCount(req.user.id);const softCancelLimit=Number(await setting('softCancelMonthlyLimit',3));const requiresReviewer=priorCancels>=softCancelLimit;const settlementHours=Number(await setting('disputeSettlementHours',24));const reviewerHours=Number(await setting('reviewerResolutionHours',48));const r=await q("INSERT INTO disputes(job_id,opened_by,reason,evidence,settlement_deadline,reviewer_action_deadline,kind,requires_reviewer,cancellation_code,suggested_talent_percent,client_voluntary_percent) VALUES($1,$2,$3,$4,now()+($5::text||' hours')::interval,now()+(($5+$6)::text||' hours')::interval,'CANCELLATION',$7,$8,$9,$10) RETURNING *",[j.id,req.user.id,detail.slice(0,5000),[],settlementHours,reviewerHours,requiresReviewer,code,suggested,voluntary]);await q("UPDATE jobs SET status='DISPUTED',payment_status='FROZEN' WHERE id=$1",[j.id]);await audit('CANCELLATION_REQUESTED',req.user.id,{jobId:j.id,disputeId:r.rows[0].id,code,requiresReviewer});const otherParty=String(req.user.id)===String(j.client_id)?j.talent_id:j.client_id;if(requiresReviewer){await q('INSERT INTO account_flags(user_id,job_id,kind,evidence) VALUES($1,$2,$3,$4)',[req.user.id,j.id,'REPEAT_CANCELLATION',`${priorCancels+1} cancellations opened in the last 30 days`]);io.to('reviewers').emit('dispute:new',{disputeId:r.rows[0].id,jobTitle:j.title});notifyAdmin('Repeat cancellation flagged',`${req.user.name} has opened ${priorCancels+1} cancellations in 30 days (latest: "${j.title}"). This one has been routed straight to reviewer review instead of allowing instant self-settlement — check Admin -> Users.`);await notify(otherParty,'CANCELLATION_REQUESTED','A cancellation was requested',`A cancellation was requested on "${j.title}". Because of this account's recent cancellation history it will be reviewed by a PRODILIVE reviewer rather than settled instantly.`,{jobId:j.id});}else{io.to('user:'+otherParty).emit('cancellation:requested',{jobId:j.id,disputeId:r.rows[0].id,code,suggestedTalentPercent:suggested});await notify(otherParty,'CANCELLATION_REQUESTED','A cancellation was requested',`The other party wants to cancel "${j.title}" and proposes ${suggested}% to you. Open the project to accept or ask a reviewer to step in.`,{jobId:j.id});}res.status(201).json(r.rows[0])}catch(e){next(e)}});
app.post('/api/disputes/:id/respond',auth,async(req,res,next)=>{try{const d=(await q('SELECT d.*,j.client_id,j.talent_id,j.title FROM disputes d JOIN jobs j ON j.id=d.job_id WHERE d.id=$1',[req.params.id])).rows[0];if(!d)return res.sendStatus(404);if(![d.client_id,d.talent_id].includes(req.user.id)||String(req.user.id)===String(d.opened_by))return res.status(403).json({error:'Only the other party on this project can respond'});if(d.kind!=='CANCELLATION'||d.requires_reviewer)return res.status(400).json({error:'This case requires a reviewer decision and cannot be self-settled'});if(d.status!=='OPEN'||d.reviewer_intervened_at)return res.status(400).json({error:'This case is no longer open for a direct response'});const action=req.body.action;if(!['ACCEPT','ESCALATE'].includes(action))return res.status(400).json({error:'Invalid action'});if(action==='ESCALATE'){const reason=String(req.body.reason||'').trim();if(reason.length<5)return res.status(400).json({error:'Please explain why you disagree with the proposed terms'});await q("UPDATE disputes SET counterparty_response='ESCALATED',counterparty_responded_at=now() WHERE id=$1",[d.id]);await audit('CANCELLATION_ESCALATED',req.user.id,{disputeId:d.id});io.to('reviewers').emit('dispute:new',{disputeId:d.id,jobTitle:d.title});notifyAdmin('Cancellation contested',`"${d.title}": the counterparty disagreed with the proposed cancellation split. A reviewer can now claim it immediately. Reason: ${reason}`);return res.json({ok:true,status:'escalated'});}const talentPercent=Math.max(Number(d.suggested_talent_percent||0),Number(d.client_voluntary_percent||0));const decision={outcome:'SETTLED_BY_PARTIES',reason:'Cancellation terms accepted by the other party',clientPercent:100-talentPercent,talentPercent,resolvedByParties:true,decidedAt:now()};await q('UPDATE disputes SET counterparty_response=$1,counterparty_responded_at=now() WHERE id=$2',['ACCEPTED',d.id]);const{payoutNote}=await applySettlementDecision(d,{id:d.job_id,client_id:d.client_id},decision,req.user.id);await audit('CANCELLATION_ACCEPTED',req.user.id,{disputeId:d.id,talentPercent});notify(d.opened_by,'CANCELLATION_ACCEPTED','Cancellation settled',`"${d.title}" was cancelled and settled: ${talentPercent}% to the talent, ${100-talentPercent}% refunded.`,{jobId:d.job_id});res.json({ok:true,status:'settled',talentPercent,payoutNote})}catch(e){next(e)}});
