async function refundDisputeShare(job,payment,clientPercent,actorId){
  const pct=Number(clientPercent||0); if(pct<=0)return null;
  const gross=Math.round(Number(payment.amount)*pct)/100;
  if(gross<=0)return null;
  const ref=`PRODILIVE_DISPUTE_REFUND_${job.id}_${payment.id}_${pct}`;
  if(payment.provider==='WALLET'){
    if(!(await q('SELECT 1 FROM wallet_ledger WHERE reference=$1',[ref])).rowCount)await q("INSERT INTO wallet_ledger(user_id,type,amount,reference,status,meta) VALUES($1,'REFUND',$2,$3,'COMPLETED',$4)",[job.client_id,gross,ref,JSON.stringify({jobId:job.id,paymentId:payment.id,clientPercent:pct})]);
    await q("UPDATE payments SET status=$1 WHERE id=$2",[pct>=100?'REFUNDED':'PARTIAL_REFUND',payment.id]);
    return {provider:'WALLET',amount:gross};
  }
  const refund=await paystack('/refund','POST',{transaction:payment.reference,amount:Math.round(gross*100)});
  await q("UPDATE payments SET status=$1,provider_payload=$2 WHERE id=$3",[pct>=100?'REFUND_PROCESSING':'PARTIAL_REFUND_PROCESSING',refund,payment.id]);
  return {provider:'PAYSTACK',amount:gross};
}

app.post('/api/reviewer/disputes/:id/escalate',auth,roles('reviewer','admin'),(req,res,next)=>req.user.role==='admin'?next():requireActiveReviewer(req,res,next),async(req,res,next)=>{try{const d=(await q('SELECT d.*,j.title FROM disputes d JOIN jobs j ON j.id=d.job_id WHERE d.id=$1',[req.params.id])).rows[0];if(!d)return res.sendStatus(404);if(req.user.role==='reviewer'&&String(d.assigned_reviewer_id)!==String(req.user.id))return res.status(403).json({error:'Not assigned'});const reason=String(req.body.reason||'').trim().slice(0,5000);if(reason.length<5)return res.status(400).json({error:'Please provide an escalation reason'});await q("UPDATE disputes SET status='ADMIN_REVIEW',decision=$1 WHERE id=$2",[JSON.stringify({outcome:'ESCALATED',reason,reviewerId:req.user.id,escalatedAt:now(),requiresAdmin:true}),d.id]);await audit('REVIEWER_ESCALATED_DISPUTE',req.user.id,{disputeId:d.id,reason});notifyAdmin('Reviewer escalated a transaction',`“${d.title}” was escalated by its reviewer. Reason: ${reason}. Funds remain frozen until Admin resolves it.`);res.json({ok:true,status:'ADMIN_REVIEW'})}catch(e){next(e)}});
app.post('/api/reviewer/disputes/:id/decision',auth,roles('reviewer','admin'),(req,res,next)=>req.user.role==='admin'?next():requireActiveReviewer(req,res,next),async(req,res,next)=>{try{const d=(await q('SELECT d.*,j.budget,j.title FROM disputes d JOIN jobs j ON j.id=d.job_id WHERE d.id=$1 OR d.job_id=$1 ORDER BY CASE WHEN d.id=$1 THEN 0 ELSE 1 END LIMIT 1',[req.params.id])).rows[0];if(!d)return res.sendStatus(404);if(req.user.role==='reviewer'&&String(d.assigned_reviewer_id)!==String(req.user.id))return res.status(403).json({error:'Not assigned'});const outcome=req.body.outcome;if(!['RELEASE_TALENT','REFUND_CLIENT','SPLIT'].includes(outcome))return res.status(400).json({error:'Invalid outcome'});let cp=Number(req.body.clientPercent||0),tp=Number(req.body.talentPercent||0);if(outcome==='RELEASE_TALENT'){cp=0;tp=100}else if(outcome==='REFUND_CLIENT'){cp=100;tp=0}else if(cp+tp!==100)return res.status(400).json({error:'Split percentages must total 100'});const threshold=Number(await setting('reviewerAutoResolveLimit',100000));const mustEscalate=req.user.role!=='admin'&&(Number(d.budget)>threshold||outcome==='SPLIT'||req.body.escalate===true);const decision={outcome,reason:String(req.body.reason||'').slice(0,5000),clientPercent:cp,talentPercent:tp,reviewerId:req.user.id,decidedAt:now(),requiresAdmin:mustEscalate};if(mustEscalate){await q("UPDATE disputes SET status='ADMIN_REVIEW',decision=$1 WHERE id=$2",[JSON.stringify(decision),d.id]);await audit('DISPUTE_RECOMMENDED_FOR_ADMIN',req.user.id,{disputeId:d.id,outcome,budget:Number(d.budget)});notifyAdmin('Dispute needs admin review',`Reviewer recommendation for “${d.title}”: ${outcome}. Amount: ${d.budget}. No funds have moved. Review it in Admin → Disputes.`);return res.json({dispute:{...d,decision,status:'ADMIN_REVIEW'},requiresAdmin:true})}await q("UPDATE disputes SET status='DECIDED',decision=$1 WHERE id=$2",[JSON.stringify(decision),d.id]);const j=(await q("UPDATE jobs SET status='RESOLVED_RELEASE',payment_status='RELEASE_PENDING',resolution=$1 WHERE id=$2 RETURNING *",[JSON.stringify(decision),d.job_id])).rows[0];await audit('DISPUTE_DECIDED',req.user.id,{disputeId:d.id,outcome});if(cp>0){try{const p=(await q('SELECT * FROM payments WHERE job_id=$1 ORDER BY created_at DESC LIMIT 1',[j.id])).rows[0];if(p&&['HELD','RELEASE_PENDING','FROZEN'].includes(p.status)){await refundDisputeShare(j,p,cp,req.user.id)}}catch(e){console.error('Dispute refund failed:',e.message);notifyAdmin('Dispute refund failed',`Job ${j.id}: ${e.message}`)}}let payoutNote=null;if(tp>0){try{await releasePayoutForJob(j.id,req.user.id)}catch(e){payoutNote=e.message}}if(req.user.role==='reviewer'){try{const feePercent=Number(await setting('reviewerFeePercent',5)),fee=Math.round(Number(j.budget)*feePercent/100*100)/100;if(fee>0)await q('INSERT INTO reviewer_ledger(reviewer_id,dispute_id,job_id,amount,status) VALUES($1,$2,$3,$4,$5)',[req.user.id,d.id,j.id,fee,'AVAILABLE'])}catch(e){console.error('Reviewer fee credit failed:',e.message)}}res.json({dispute:{...d,decision,status:'DECIDED'},job:publicJob(j),payoutNote,requiresAdmin:false})}catch(e){next(e)}});
app.post('/api/admin/disputes/:id/finalize',auth,roles('admin'),async(req,res,next)=>{try{const d=(await q("SELECT d.*,j.budget,j.title FROM disputes d JOIN jobs j ON j.id=d.job_id WHERE d.id=$1 AND d.status='ADMIN_REVIEW'",[req.params.id])).rows[0];if(!d)return res.status(404).json({error:'Escalated dispute not found'});const rec=json(d.decision)||{},outcome=req.body.outcome||rec.outcome;let cp=Number(req.body.clientPercent??rec.clientPercent??0),tp=Number(req.body.talentPercent??rec.talentPercent??0);if(outcome==='RELEASE_TALENT'){cp=0;tp=100}else if(outcome==='REFUND_CLIENT'){cp=100;tp=0}else if(outcome!=='SPLIT'||cp+tp!==100)return res.status(400).json({error:'Invalid final resolution'});const decision={...rec,outcome,clientPercent:cp,talentPercent:tp,adminId:req.user.id,adminReason:String(req.body.reason||'').slice(0,5000),finalizedAt:now(),requiresAdmin:false};await q("UPDATE disputes SET status='DECIDED',decision=$1 WHERE id=$2",[JSON.stringify(decision),d.id]);const j=(await q("UPDATE jobs SET status='RESOLVED_RELEASE',payment_status='RELEASE_PENDING',resolution=$1 WHERE id=$2 RETURNING *",[JSON.stringify(decision),d.job_id])).rows[0];if(cp>0){try{const p=(await q('SELECT * FROM payments WHERE job_id=$1 ORDER BY created_at DESC LIMIT 1',[j.id])).rows[0];if(p&&['HELD','RELEASE_PENDING','FROZEN'].includes(p.status)){await refundDisputeShare(j,p,cp,req.user.id)}}catch(e){console.error('Admin dispute refund failed:',e.message)}}let payoutNote=null;if(tp>0){try{await releasePayoutForJob(j.id,req.user.id)}catch(e){payoutNote=e.message}}await audit('ADMIN_FINALIZED_DISPUTE',req.user.id,{disputeId:d.id,outcome});res.json({dispute:{...d,decision,status:'DECIDED'},job:publicJob(j),payoutNote})}catch(e){next(e)}});

