app.put('/api/me/payout-profile',auth,roles('member','reviewer','talent','client'),async(req,res)=>{try{const country=String(req.body.country||'NG').toUpperCase(),m=PAYOUT_MARKETS[country];const bankCode=String(req.body.bankCode||'').trim(),bankName=String(req.body.bankName||'').trim().slice(0,160),accountNumber=String(req.body.accountNumber||'').trim();if(!m)return res.status(400).json({error:'Unsupported payout country'});if(!bankCode||accountNumber.length<5)return res.status(400).json({error:'Please choose a bank and enter a valid account number'});if(!m.autoName)return res.status(400).json({error:`Automatic verified bank withdrawals for ${m.name} are not enabled by the current Paystack account. Choose a supported verified payout method.`});const resolved=await paystack('/bank/resolve?account_number='+encodeURIComponent(accountNumber)+'&bank_code='+encodeURIComponent(bankCode));const accountName=String(resolved.account_name||'').trim();if(!accountName)return res.status(400).json({error:'That account could not be verified'});await q('UPDATE users SET bank_code=$1,payout_bank_name=$2,account_number=$3,account_name=$4,paystack_recipient_code=NULL,payout_country=$5,payout_currency=$6,payout_recipient_type=$7,payout_account_verified=true,payout_account_verified_at=now() WHERE id=$8',[bankCode,bankName,accountNumber,accountName,country,m.currency,m.recipientType,req.user.id]);await audit('PAYOUT_PROFILE_UPDATED',req.user.id,{bankCode,country,currency:m.currency,accountVerified:true});res.json({ok:true,accountName,country,currency:m.currency})}catch(e){console.error('Payout profile failed:',e.message);res.status(400).json({error:e.message||'Could not save payout details'})}});
app.post('/api/admin/payments/:jobId/refund',auth,roles('admin'),async(req,res,next)=>{try{const p=(await q(`SELECT p.*,j.title,j.status,j.client_id FROM payments p JOIN jobs j ON j.id=p.job_id WHERE p.job_id=$1 ORDER BY p.created_at DESC LIMIT 1`,[req.params.jobId])).rows[0];if(!p)return res.status(404).json({error:'Payment not found'});if(!['HELD','RELEASE_PENDING','FROZEN'].includes(p.status))return res.status(400).json({error:'Payment is not refundable in its current state'});const amount=Math.round(Number(p.amount)*100);const refund=await paystack('/refund','POST',{transaction:p.reference,amount});await q("UPDATE payments SET status='REFUND_PROCESSING',provider_payload=$1 WHERE id=$2",[refund,p.id]);await q("UPDATE jobs SET payment_status='REFUND_PENDING',status='DISPUTED' WHERE id=$1",[p.job_id]);await audit('REFUND_INITIATED',req.user.id,{jobId:p.job_id,reference:p.reference,amount:amount/100});res.json({ok:true,refund})}catch(e){next(e)}});

async function releasePayoutForJob(jobId,initiatedByUserId){
  const c=await q('SELECT value FROM settings WHERE key=$1',['commission']);
  const commission=Number(c.rowCount?json(c.rows[0].value):12);
  const j=(await q('SELECT * FROM jobs WHERE id=$1',[jobId])).rows[0];
  if(!j||!j.talent_id)throw Object.assign(new Error('Job/talent not found'),{status:404});
  if(j.payment_status!=='RELEASE_PENDING')throw Object.assign(new Error('Payment not ready for release'),{status:400});
  const reference=`PRODILIVE_EARNING_${j.id}`;
  const already=await q('SELECT 1 FROM wallet_ledger WHERE reference=$1',[reference]);
  if(already.rowCount)return{jobId:j.id,alreadyReleased:true};
  const percent=Number(j.resolution?.talentPercent??100);
  const amount=Math.round(Number(j.budget)*percent/100*(1-commission/100)*100)/100;
  if(amount<=0)throw Object.assign(new Error('Payout amount is zero'),{status:400});
  await q("INSERT INTO wallet_ledger(user_id,type,amount,reference,status,meta) VALUES($1,'JOB_EARNING',$2,$3,'COMPLETED',$4)",[j.talent_id,amount,reference,JSON.stringify({jobId:j.id,commission,percent})]);
  const gross=Math.round(Number(j.budget)*percent/100*100)/100,platformCommission=Math.round((gross-amount)*100)/100;if(platformCommission>0)await q("INSERT INTO platform_ledger(type,amount,reference,meta) VALUES('JOB_COMMISSION',$1,$2,$3) ON CONFLICT(reference) DO NOTHING",[platformCommission,'PLATFORM_JOB_'+reference,JSON.stringify({jobId:j.id,commission,percent})]);
  await q("UPDATE jobs SET payment_status='RELEASED',status='RELEASED' WHERE id=$1",[j.id]);
  await audit('PAYOUT_CREDITED_TO_WALLET',initiatedByUserId,{jobId:j.id,amount});
  await notify(j.talent_id,'PAYOUT',`You earned ${amount}`,`Your earnings for "${j.title}" (${amount}) have landed in your PRODILIVE wallet instantly. Withdraw any time from your dashboard.`,{jobId:j.id});
  return{jobId:j.id,amount};
}
