app.post('/api/messages/:jobId',auth,requireVerified,async(req,res,next)=>{try{const j=(await q('SELECT id,client_id,talent_id,title FROM jobs WHERE id=$1',[req.params.jobId])).rows[0];if(!j)return res.sendStatus(404);let allowed=[j.client_id,j.talent_id].map(String).includes(String(req.user.id))||req.user.role==='admin';if(!allowed&&req.user.role==='reviewer'){allowed=Boolean((await q("SELECT 1 FROM disputes WHERE job_id=$1 AND assigned_reviewer_id=$2 AND status IN ('ASSIGNED','ADMIN_REVIEW')",[j.id,req.user.id])).rowCount)}if(!allowed)return res.sendStatus(403);const body=String(req.body.body||'').trim();if(!body||body.length>5000)return res.status(400).json({error:'Message must be 1-5000 characters'});const offPlatform=/(whats ?app|telegram|instagram|dm me|text me|call me|pay me direct|bank transfer|outside (the )?app|@\w{3,}|\b(?:\+?234|0)[789][01]\d{8}\b|[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i.test(body);if(offPlatform){await q('INSERT INTO account_flags(user_id,job_id,kind,evidence) VALUES($1,$2,$3,$4)',[req.user.id,j.id,'OFF_PLATFORM_CONTACT',body.slice(0,1000)]);await audit('OFF_PLATFORM_CHAT_FLAG',req.user.id,{jobId:j.id});notifyAdmin('Off-platform contact flag',`A message on “${j.title}” may be attempting to move communication/payment outside PRODILIVE. Review the project chat.`)}const r=await q('INSERT INTO messages(job_id,sender_id,body) VALUES($1,$2,$3) RETURNING *',[j.id,req.user.id,body]);for(const uid of [j.client_id,j.talent_id])if(uid&&String(uid)!==String(req.user.id))await notify(uid,'MESSAGE',`${req.user.role==='admin'?'Admin':req.user.role==='reviewer'?'Reviewer':req.user.name} · “${j.title}”`,body.slice(0,200),{jobId:j.id,messageId:r.rows[0].id});const outMsg={...r.rows[0],sender_name:req.user.name,sender_role:req.user.role};io.to('job:'+j.id).emit('message:new',outMsg);res.status(201).json(outMsg)}catch(e){next(e)}});

