app.post('/api/admin/verifications/:id/decision',auth,roles('admin'),async(req,res,next)=>{try{const approved=Boolean(req.body.approved);const r=await q("UPDATE users SET verification_status=$1,verification_reviewed_at=now(),reviewer_status=CASE WHEN role='reviewer' AND $1='APPROVED' THEN 'TERMS_PENDING' WHEN role='reviewer' AND $1='REJECTED' THEN 'IDENTITY_REJECTED' ELSE reviewer_status END WHERE id=$2 RETURNING *",[approved?'APPROVED':'REJECTED',req.params.id]);if(!r.rowCount)return res.sendStatus(404);await notify(r.rows[0].id,'VERIFICATION',approved?'Identity verified':'Verification needs another look',approved?'Your provider identity document was approved. You can now apply to and claim projects.':'Your identity document was rejected — please upload a clearer copy from your dashboard.',{});await audit('ADMIN_VERIFICATION_DECISION',req.user.id,{userId:req.params.id,approved});res.json({user:cleanUser(r.rows[0])})}catch(e){next(e)}});
app.get('/api/admin/audit',auth,roles('admin'),async(req,res,next)=>{try{
  const limit=Math.max(1,Math.min(1000,Number(req.query.limit||300)));
  const r=await q('SELECT id,action,actor AS actor_id,COALESCE(meta,\'{}\'::jsonb) AS meta,at FROM audit ORDER BY at DESC NULLS LAST LIMIT $1',[limit]);
  res.json({audit:r.rows,error:null});
}catch(e){
  console.error('Admin audit log load failed:',e.message);
  // Never let a diagnostics screen blank the Admin workspace. Return a safe payload
  // and let the UI show the database error while every other Admin tab remains usable.
  res.status(200).json({audit:[],error:'Audit history is temporarily unavailable. '+String(e.message||'').slice(0,240)});
}});
