app.get('/api/admin/reviewers',auth,roles('admin'),async(req,res,next)=>{try{
  // Include current Reviewer accounts AND legacy accepted reviewers from the older
  // application flow. Older Prodilive builds could leave an accepted reviewer with
  // a member/client/talent role, which made them disappear from the new Admin list.
  const r=await q(`
    SELECT u.*,
      COUNT(DISTINCT d.id)::int assigned_cases,
      COUNT(DISTINCT d.id) FILTER (WHERE d.status='DECIDED')::int resolved_cases,
      BOOL_OR(ra.status='APPROVED') AS legacy_approved
    FROM users u
    LEFT JOIN disputes d ON d.assigned_reviewer_id=u.id
    LEFT JOIN reviewer_applications ra ON ra.user_id=u.id
    WHERE u.role='reviewer'
       OR ra.status='APPROVED'
       OR u.reviewer_score IS NOT NULL
       OR u.reviewer_level IS NOT NULL
    GROUP BY u.id
    ORDER BY u.created_at DESC`);
  res.json({reviewers:r.rows.map(x=>({...cleanUser(x),assignedCases:Number(x.assigned_cases||0),resolvedCases:Number(x.resolved_cases||0),legacyReviewer:x.role!=='reviewer'}))});
}catch(e){next(e)}});
