/* ============================ REVIEWER ↔ ADMIN CASE CHAT ============================ */
async function reviewerAdminChatAccess(disputeId,user){
  const d=(await q('SELECT id,job_id,assigned_reviewer_id,status FROM disputes WHERE id=$1',[disputeId])).rows[0];
  if(!d)return {error:404};
  if(user.role==='admin')return {dispute:d};
  if(user.role==='reviewer'&&String(d.assigned_reviewer_id||'')===String(user.id))return {dispute:d};
  return {error:403};
}
app.get('/api/disputes/:id/reviewer-admin-chat',auth,roles('admin','reviewer'),async(req,res,next)=>{try{
  const access=await reviewerAdminChatAccess(req.params.id,req.user);if(access.error)return res.sendStatus(access.error);
  const r=await q('SELECT m.id,m.sender_id,m.sender_role,m.body,m.created_at FROM reviewer_admin_messages m WHERE m.dispute_id=$1 ORDER BY m.created_at ASC',[req.params.id]);
  res.json({messages:r.rows.map(m=>({id:m.id,senderId:m.sender_id,senderRole:m.sender_role,body:m.body,createdAt:m.created_at}))});
}catch(e){next(e)}});
app.post('/api/disputes/:id/reviewer-admin-chat',auth,roles('admin','reviewer'),async(req,res,next)=>{try{
  const access=await reviewerAdminChatAccess(req.params.id,req.user);if(access.error)return res.sendStatus(access.error);
  const body=String(req.body.body||'').trim().slice(0,4000);if(!body)return res.status(400).json({error:'Message cannot be empty'});
  await q('INSERT INTO reviewer_admin_messages(dispute_id,sender_id,sender_role,body) VALUES($1,$2,$3,$4)',[req.params.id,req.user.id,req.user.role,body]);
  if(req.user.role==='reviewer') notifyAdmin('Reviewer case message',`${req.user.name} sent a private Admin message on dispute ${req.params.id}.\n\nOpen Admin → Disputes to reply.`);
  else if(access.dispute.assigned_reviewer_id) await notify(access.dispute.assigned_reviewer_id,'REVIEWER_ADMIN_CHAT','New Admin case message','PRODILIVE Admin sent you a private message about a dispute you are handling.',{disputeId:req.params.id});
  await audit('REVIEWER_ADMIN_CHAT_MESSAGE',req.user.id,{disputeId:req.params.id,role:req.user.role});
  const r=await q('SELECT id,sender_id,sender_role,body,created_at FROM reviewer_admin_messages WHERE dispute_id=$1 ORDER BY created_at ASC',[req.params.id]);
  res.status(201).json({messages:r.rows.map(m=>({id:m.id,senderId:m.sender_id,senderRole:m.sender_role,body:m.body,createdAt:m.created_at}))});
}catch(e){next(e)}});

/* ============================ SUPPORT CHAT ============================ */
const publicThread = t => ({ id:t.id, status:t.status, createdAt:t.created_at });
const publicSMsg = m => ({ id:m.id, senderType:m.sender_type, senderName:m.sender_name, body:m.body, createdAt:m.created_at });

app.post('/api/support/message',optionalAuth,async(req,res,next)=>{try{
  const body=String(req.body.body||'').trim().slice(0,3000);
  if(!body)return res.status(400).json({error:'Message cannot be empty'});
  let threadId=req.body.threadId?String(req.body.threadId):null;
  let thread=null;
  if(threadId){thread=(await q('SELECT * FROM support_threads WHERE id=$1',[threadId])).rows[0]||null;
    if(thread&&req.user&&thread.user_id&&thread.user_id!==req.user.id)thread=null;
    if(thread&&!req.user&&req.body.guestToken&&thread.guest_token!==String(req.body.guestToken))thread=null;
  }
  if(!thread&&req.user){thread=(await q("SELECT * FROM support_threads WHERE user_id=$1 AND status='OPEN' ORDER BY created_at DESC LIMIT 1",[req.user.id])).rows[0]||null;}
  if(!thread){
    const guestToken=req.user?null:String(req.body.guestToken||crypto.randomUUID());
    const name=req.user?req.user.name:String(req.body.name||'Guest').slice(0,100);
    const email=req.user?req.user.email:String(req.body.email||'').slice(0,200);
    thread=(await q('INSERT INTO support_threads(user_id,guest_token,guest_name,guest_email) VALUES($1,$2,$3,$4) RETURNING *',[req.user?req.user.id:null,guestToken,name,email])).rows[0];
  }
  const senderName=req.user?req.user.name:(thread.guest_name||'Guest');
  const m=(await q("INSERT INTO support_messages(thread_id,sender_type,sender_name,body) VALUES($1,'visitor',$2,$3) RETURNING *",[thread.id,senderName,body])).rows[0];
  const msgs=(await q('SELECT * FROM support_messages WHERE thread_id=$1 ORDER BY created_at',[thread.id])).rows;
  res.status(201).json({thread:publicThread(thread),guestToken:thread.guest_token,messages:msgs.map(publicSMsg)});
}catch(e){next(e)}});

app.get('/api/support/thread/:id',optionalAuth,async(req,res,next)=>{try{
  const thread=(await q('SELECT * FROM support_threads WHERE id=$1',[req.params.id])).rows[0];
  if(!thread)return res.sendStatus(404);
  const owns=(req.user&&thread.user_id===req.user.id)||(!req.user&&req.query.guestToken&&thread.guest_token===String(req.query.guestToken));
  if(!owns)return res.sendStatus(403);
  const msgs=(await q('SELECT * FROM support_messages WHERE thread_id=$1 ORDER BY created_at',[thread.id])).rows;
  res.json({thread:publicThread(thread),messages:msgs.map(publicSMsg)});
}catch(e){next(e)}});

app.get('/api/admin/support',auth,roles('admin'),async(req,res,next)=>{try{
  const r=await q(`SELECT t.*,u.name user_name,u.email user_email,
    (SELECT body FROM support_messages m WHERE m.thread_id=t.id ORDER BY created_at DESC LIMIT 1) last_body,
    (SELECT created_at FROM support_messages m WHERE m.thread_id=t.id ORDER BY created_at DESC LIMIT 1) last_at
    FROM support_threads t LEFT JOIN users u ON u.id=t.user_id ORDER BY last_at DESC NULLS LAST LIMIT 200`);
  res.json({threads:r.rows.map(t=>({id:t.id,status:t.status,name:t.user_name||t.guest_name,email:t.user_email||t.guest_email,lastBody:t.last_body,lastAt:t.last_at,createdAt:t.created_at}))});
}catch(e){next(e)}});

app.get('/api/admin/support/:id',auth,roles('admin'),async(req,res,next)=>{try{
  const thread=(await q('SELECT t.*,u.name user_name,u.email user_email FROM support_threads t LEFT JOIN users u ON u.id=t.user_id WHERE t.id=$1',[req.params.id])).rows[0];
  if(!thread)return res.sendStatus(404);
  const msgs=(await q('SELECT * FROM support_messages WHERE thread_id=$1 ORDER BY created_at',[thread.id])).rows;
  res.json({thread:{...publicThread(thread),name:thread.user_name||thread.guest_name,email:thread.user_email||thread.guest_email},messages:msgs.map(publicSMsg)});
}catch(e){next(e)}});

app.post('/api/admin/support/:id/reply',auth,roles('admin'),async(req,res,next)=>{try{
  const body=String(req.body.body||'').trim().slice(0,3000);
  if(!body)return res.status(400).json({error:'Message cannot be empty'});
  const thread=(await q('SELECT * FROM support_threads WHERE id=$1',[req.params.id])).rows[0];
  if(!thread)return res.sendStatus(404);
  await q("INSERT INTO support_messages(thread_id,sender_type,sender_name,body) VALUES($1,'admin',$2,$3)",[thread.id,req.user.name,body]);
  if(thread.user_id)await notify(thread.user_id,'SUPPORT_REPLY','New support reply','PRODILIVE support replied to your message.',{threadId:thread.id});
  const msgs=(await q('SELECT * FROM support_messages WHERE thread_id=$1 ORDER BY created_at',[thread.id])).rows;
  res.json({messages:msgs.map(publicSMsg)});
}catch(e){next(e)}});

app.post('/api/admin/support/:id/close',auth,roles('admin'),async(req,res,next)=>{try{
  const r=await q("UPDATE support_threads SET status='CLOSED' WHERE id=$1 RETURNING *",[req.params.id]);
  if(!r.rowCount)return res.sendStatus(404);
  res.json({thread:publicThread(r.rows[0])});
}catch(e){next(e)}});

