app.post('/api/me/sms/test',auth,async(req,res,next)=>{try{if(!smsConfigured)return res.status(503).json({error:'Robase SMS is not configured'});const r=await q('SELECT phone,phone_verified,sms_job_alerts FROM users WHERE id=$1',[req.user.id]);const u=r.rows[0];if(!u?.phone)return res.status(400).json({error:'Add a phone number in Profile first'});if(!u.phone_verified)return res.status(400).json({error:'Verify your phone number first'});const result=await sendUserFundedSms(req.user.id,u.phone,'PRODILIVE SMS test successful. Your paid SMS alerts are connected.','test');if(!result.sent){const messages={insufficient_wallet_balance:`Your SMS setting is working, but your wallet balance is too low. This test costs NGN ${result.price||0}.`,provider_failed:'Robase rejected or failed the SMS. Check the Robase dashboard/logs.',sms_not_configured:'Robase SMS is not configured.'};return res.status(400).json({error:messages[result.reason]||'SMS could not be sent',reason:result.reason});}res.json({ok:true,provider:'robase',charged:result.price,providerId:result.providerId})}catch(e){next(e)}});
app.get('/api/admin/integrations/diagnostics',auth,roles('admin'),async(req,res,next)=>{try{let r2Reachable=false,robaseReachable=false;let r2Error=null,robaseError=null;if(s3){try{await s3.send(new ListObjectsV2Command({Bucket:R2_BUCKET,MaxKeys:1}));r2Reachable=true}catch(e){r2Error=String(e.message||e).slice(0,160)}}if(smsConfigured){try{const rr=await robaseRequest('/v1/pricing');robaseReachable=Boolean(rr)}catch(e){robaseError=String(e.message||e).slice(0,160)}}res.json({email:{configured:emailConfigured,provider:RESEND_API_KEY?'resend':(smtpMailer?'smtp':null),apiKeyPresent:Boolean(RESEND_API_KEY),fromConfigured:Boolean(RESEND_FROM||process.env.MAIL_FROM)},storage:{configured:Boolean(s3),reachable:r2Reachable,error:r2Error},sms:{configured:smsConfigured,provider:'robase',reachable:robaseReachable,error:robaseError},paystack:{configured:Boolean(process.env.PAYSTACK_SECRET_KEY)}})}catch(e){next(e)}});
app.get('/api/public-config',(req,res)=>res.json({tawkPropertyId:String(process.env.TAWK_PROPERTY_ID||'').trim(),tawkWidgetId:String(process.env.TAWK_WIDGET_ID||'').trim()}));
