async function processOverdueJobs(){
  try{
    const alertJobs=(await q("SELECT * FROM jobs WHERE deadline IS NOT NULL AND talent_id IS NOT NULL AND status IN ('IN_PROGRESS','REVISION_REQUESTED','AWAITING_PAYMENT') AND deadline>now() AND deadline<=now()+interval '48 hours' LIMIT 200")).rows;
    for(const j of alertJobs){try{const hrs=(new Date(j.deadline).getTime()-Date.now())/3600000;const bucket=hrs<=1?'1h':hrs<=6?'6h':hrs<=24?'24h':'48h';const sent=Array.isArray(j.deadline_alerts_sent)?j.deadline_alerts_sent:json(j.deadline_alerts_sent,[]);if(sent.includes(bucket))continue;const title=`${bucket.replace('h',' hour')} delivery reminder`;const body=`“${j.title}” is due ${new Date(j.deadline).toLocaleString()}.`;await notifyWithPrefs(j.talent_id,'DEADLINE_REMINDER',title,body,{jobId:j.id,deadline:j.deadline},'deadline');await notifyWithPrefs(j.client_id,'DEADLINE_REMINDER',title,body,{jobId:j.id,deadline:j.deadline},'deadline');await q('UPDATE jobs SET deadline_alerts_sent=$1 WHERE id=$2',[JSON.stringify([...sent,bucket]),j.id]);}catch(e){console.error('Deadline alert failed',j.id,e.message)}}
    const jobs=(await q("SELECT * FROM jobs WHERE auto_cancel_overdue=true AND deadline IS NOT NULL AND submitted_at IS NULL AND status IN ('IN_PROGRESS','REVISION_REQUESTED') AND deadline + (overdue_grace_hours::text||' hours')::interval <= now() LIMIT 50")).rows;
    for(const j of jobs){
      const p=(await q('SELECT * FROM payments WHERE job_id=$1 ORDER BY created_at DESC LIMIT 1',[j.id])).rows[0];
      try{
        if(p&&p.status==='HELD'){
          if(p.provider==='WALLET'){
            const ref='AUTO_CANCEL_REFUND_'+j.id+'_'+p.id;
            if(!(await q('SELECT 1 FROM wallet_ledger WHERE reference=$1',[ref])).rowCount)await q("INSERT INTO wallet_ledger(user_id,type,amount,reference,status,meta) VALUES($1,'REFUND',$2,$3,'COMPLETED',$4)",[j.client_id,Number(p.amount),ref,JSON.stringify({jobId:j.id,autoCancel:true})]);
            await q("UPDATE payments SET status='REFUNDED' WHERE id=$1",[p.id]);
          }else{
            const refund=await paystack('/refund','POST',{transaction:p.reference,amount:Math.round(Number(p.amount)*100)});
            await q("UPDATE payments SET status='REFUND_PROCESSING',provider_payload=$1 WHERE id=$2",[refund,p.id]);
          }
        }
        await q("UPDATE jobs SET status='CANCELLED',payment_status=CASE WHEN payment_status='HELD' THEN 'REFUND_PENDING' ELSE payment_status END WHERE id=$1",[j.id]);
        await notify(j.client_id,'JOB_AUTO_CANCELLED','Project auto-cancelled',`“${j.title}” was automatically cancelled after its delivery deadline and grace period expired.`,{jobId:j.id});
        if(j.talent_id)await notify(j.talent_id,'JOB_AUTO_CANCELLED','Project auto-cancelled',`“${j.title}” was automatically cancelled after its delivery deadline and grace period expired.`,{jobId:j.id});
        await audit('JOB_AUTO_CANCELLED','SYSTEM',{jobId:j.id});
      }catch(e){console.error('Auto-cancel job failed',j.id,e.message)}
    }
  }catch(e){console.error('Overdue job scan failed:',e.message)}
}
async function runPendingMigrations(){
  try{
    await q('CREATE TABLE IF NOT EXISTS schema_migrations(id text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now())');
    const dir=path.join(ROOT,'migrations');
    if(!fs.existsSync(dir))return;
    const files=fs.readdirSync(dir).filter(f=>f.endsWith('.sql')).sort();
    const done=new Set((await q('SELECT id FROM schema_migrations')).rows.map(r=>r.id));
    for(const file of files){
      if(done.has(file))continue;
      const raw=fs.readFileSync(path.join(dir,file),'utf8');
      // Strip psql-only meta-commands (e.g. \i ../db/schema.sql) — those are
      // client-side directives, not real SQL, and the base schema they
      // reference is already applied on any existing production database.
      const sql=raw.split('\n').filter(line=>!line.trim().startsWith('\\')).join('\n');
      console.log('Running migration:',file);
      if(sql.trim())await pool.query(sql);
      await q('INSERT INTO schema_migrations(id) VALUES($1)',[file]);
      console.log('Migration applied:',file);
    }
  }catch(e){console.error('Migration runner failed:',e.message)}
}

