const server=createServer(app);
const io=new SocketIOServer(server,{cors:{origin:allowedOrigins.length?allowedOrigins:false,methods:['GET','POST']}});
async function socketUserFromToken(token){ const r=await q(`SELECT u.id,u.role FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=$1 AND s.expires_at>now()`,[sha(String(token||''))]); return r.rows[0]||null; }
io.on('connection',(socket)=>{
  socket.on('join:reviewers',async(token)=>{
    try{const u=await socketUserFromToken(token);if(u&&u.role==='reviewer')socket.join('reviewers');}catch{}
  });
  socket.on('join:user',async(token)=>{
    try{const u=await socketUserFromToken(token);if(u)socket.join('user:'+u.id);}catch{}
  });
  socket.on('join:job',async({token,jobId})=>{
    try{const u=await socketUserFromToken(token);if(!u||!jobId)return;const j=(await q('SELECT client_id,talent_id FROM jobs WHERE id=$1',[jobId])).rows[0];if(!j)return;const allowed=[j.client_id,j.talent_id].map(String).includes(String(u.id))||u.role==='admin'||(u.role==='reviewer'&&(await q(`SELECT 1 FROM disputes WHERE job_id=$1 AND assigned_reviewer_id=$2 AND status IN ('ASSIGNED','ADMIN_REVIEW','DECIDED')`,[jobId,u.id])).rowCount);if(allowed)socket.join('job:'+jobId);}catch{}
  });
  socket.on('leave:job',(jobId)=>{ if(jobId)socket.leave('job:'+jobId); });
});
server.listen(PORT,()=>console.log(`PRODILIVE running on ${PORT}`));
setInterval(()=>processOverdueJobs(),5*60*1000).unref();processOverdueJobs();
async function shutdown(){server.close(()=>pool.end().then(()=>process.exit(0)));setTimeout(()=>process.exit(1),10000)}
process.on('SIGTERM',shutdown);process.on('SIGINT',shutdown);
